+.footer a:hover{text-decoration:underline;color:rgba(255,255,255,.9)}
+.footer-grid{display:grid;grid-template-columns:repeat(4, 1fr);gap:16px}
+.foot-col{display:grid;gap:12px;font-size:14px}
+.fineprint{margin-top:22px;color:rgba(255,255,255,.55);font-size:12px;max-width:72ch}
+
