+  display:grid;
+  place-items:center;
+  padding:32px 0 60px;
+}
+.auth-card{
+  width:min(520px, 100%);
+  border-radius:22px;
+  border:1px solid rgba(255,255,255,.12);
+  background:linear-gradient(180deg, rgba(20,20,20,.78), rgba(0,0,0,.60));
+  box-shadow:var(--shadow);
+  padding:22px;
+}
+.auth-card h1{margin:0;font-size:28px;font-weight:900;letter-spacing:-.4px}
+.auth-card p{margin:8px 0 0;color:var(--muted)}
+.form-grid{display:grid;gap:12px;margin-top:16px}
+.hint{margin-top:10px;color:rgba(255,255,255,.65);font-size:13px}
+.help-toggle{
+  margin-top:16px;
+  width:100%;
+  text-align:left;
+  border:0;
+  background:transparent;
+  color:rgba(255,255,255,.9);
+  cursor:pointer;
+  font-weight:800;
+  display:flex;align-items:center;justify-content:space-between;
+  padding:12px 0;
+}
+.help-toggle:focus-visible{outline:none;box-shadow:var(--ring)}
+.help-panel{max-height:0;overflow:hidden;transition:max-height .22s ease}
+.help-panel-inner{padding:0 0 10px;color:rgba(255,255,255,.72);font-size:14px}
+.help[data-open="true"] .help-panel{max-height:220px}
+
+/* Responsive */
+@media (max-width: 980px){
+  .hero-grid{grid-template-columns:1fr}
+  .email-card{max-width:680px}
+  .features{grid-template-columns:repeat(2, 1fr)}
+}
+@media (max-width: 640px){
+  .header-inner{height:66px}
+  .email-form{grid-template-columns:1fr}
+  .cta-form{grid-template-columns:1fr}
+  .btn{height:50px}
+  .card{width:190px;height:280px}
+  .rank{font-size:122px}
+  .footer-grid{grid-template-columns:repeat(2, 1fr)}
+  .mosaic{padding:66px 14px 110px;gap:8px;grid-auto-rows:64px}
+}
+
+@media (prefers-reduced-motion: reduce){
+  *{scroll-behavior:auto !important}
+  .btn,.icon-btn{transition:none}
+  .acc-panel,.help-panel{transition:none}
+}
+
